[
  {
    "title": "The Escher Height Invariant via Krull Dimension Gaps",
    "description": "Define the Escher height of a commutative ring as the supremum, over all strictly ascending chains of ideals with vanishing infinite intersection, of the Krull dimension of the quotient by the chain's first term. Conjecture that for the polynomial ring k[x_1,...,x_n] the Escher height equals n, that for k[x_1,x_2,...] it is infinite, and that a ring has Escher height 0 exactly when it is Noetherian of dimension 0 (Artinian). The proposed approach is to first establish that every non-Noetherian ring admits a strictly ascending ideal chain whose intersection is its base ideal, then to stratify such chains by the dimension of the ambient quotient and compare against known Krull-dimension computations for polynomial rings.",
    "tags": ["CommutativeAlgebra", "KrullDimension", "Noetherian"]
  },
  {
    "title": "Ascending–Descending Duality of Vanishing Intersections",
    "description": "For an ascending chain of ideals the infinite intersection is forced to equal the first term; for a descending chain the intersection can genuinely collapse to zero (the Anti-Escher phenomenon proved for dyadic ideals in the integers). Conjecture a precise duality: in a ring R, the existence of a strictly descending chain of ideals with zero intersection and nonzero terms is equivalent to R having a nonzero element lying in arbitrarily high powers of some proper ideal, i.e. failure of the Krull intersection theorem's hypotheses. Approach: relate descending collapses to the Krull intersection theorem and to completions, and classify which rings admit both an ascending Escher staircase and a nontrivial descending collapse.",
    "tags": ["CommutativeAlgebra", "KrullIntersection", "Duality"]
  },
  {
    "title": "Escher Staircases in Semirings and the Tropical Setting",
    "description": "The characterization 'strictly ascending ideal chain exists iff non-Noetherian' is proved for commutative rings. Investigate its analogue for commutative semirings, in particular the tropical semiring and semirings of the form (S -> T) with pointwise operations. Conjecture that the support-below-n construction generalizes to any product semiring over an infinite index set, always yielding a strictly ascending chain of semiring ideals with zero intersection, and that the tropical polynomial semiring in infinitely many variables is non-Noetherian in the semiring sense. Approach: define semiring ideals carefully (closure under addition and absorption), port the support construction, and test whether well-founded-order characterizations of Noetherianity survive without additive inverses.",
    "tags": ["Tropical", "Semiring", "Noetherian"]
  },
  {
    "title": "The Escher Height of the Ring of All Algebraic Integers",
    "description": "The ring of all algebraic integers is a non-Noetherian Bezout domain of Krull dimension one. Conjecture that it carries an explicit Escher staircase built from the ideals generated by successive 2^(1/2^n), that this chain is strictly ascending with intersection equal to its base, and that despite Krull dimension one the ring's Escher height (as defined via ascending chains modulo their base) is infinite because arbitrarily long strict chains exist between any two comparable ideals. Approach: use the fact that this ring is a directed union of Dedekind domains, exhibit the radical-tower chain explicitly, and prove strictness by valuation-theoretic separation of the generators.",
    "tags": ["AlgebraicNumberTheory", "BezoutDomain", "Noetherian"]
  },
  {
    "title": "Escher Staircases as a Measure of Distance from Noetherianity",
    "description": "Propose a quantitative refinement: for a ring R, define its staircase spectrum as the set of order types realizable by strictly ascending chains of ideals. Conjecture that R is Noetherian iff its staircase spectrum contains no copy of the natural numbers, that the spectrum is a Morita-style invariant stable under polynomial extension up to a shift, and that infinite-index-set product rings realize every countable ascending order type. Approach: connect the staircase spectrum to well-founded-order characterizations of the ascending chain condition, compute it for product rings and polynomial rings, and test stability under localization and quotient.",
    "tags": ["CommutativeAlgebra", "OrderTheory", "RingInvariants"]
  }
]

